using namespace std;

long n, c, i, a[1000], dif[500], savepos;

int main() {
    while (cin >> n >> c) {
        long maxDiff = 0;

        for (i = 0; i < n; ++i) {
            cin >> a[i];

            if (i > 0) {
                dif[i - 1] = a[i - 1] - a[i];

                if (dif[i - 1] > maxDiff) {
                    maxDiff = dif[i - 1];
                    savepos = i - 1;
                }
            }
        }

        if (maxDiff > 0)
            cout << maxDiff - c << '\n';
        else
            cout << 0 << '\n';
    }

    return 0;
}

